Consider the following C program:
```c
#include <stdio.h>
void stringcopy(char *, char *);
int main() {
    char a[30] = "@#Hello World!";
    stringcopy(a, a + 2);
    printf("%s\n", a);
    return 0;
}
void stringcopy(char *s, char *t) {
    while(*t)
        *s++ = *t++;
}
```
Which ONE of the following will be the output of the program?

Consider the following C code segment:
```c
int x=126, y=105;
do {
    if(x>y) x=x-y;
    else y=y-x;
} while(x!=y);
printf("%d", x);
```
The output of the given C code segment is ________. (Answer in integer)

Consider the following C program:
```c
#include <stdio.h>
int main() {
    int a;
    int arr[5] = {30, 50, 10};
    int *ptr;
    ptr = &arr[0] + 1;
    a = *ptr;
    (*ptr)++;
    ptr++;
    printf("%d", a + (*ptr) + arr[1]);
    return 0;
}
```
The output of the above program is __________. (Answer in integer)

Consider the following C program:
```c
#include <stdio.h>
int g(int n) {
    return (n + 10);
}
int f(int n) {
    return g(n * 2);
}
int main() {
    int sum, n;
    sum = 0;
    for (n = 1; n < 3; n++)
        sum += g(f(n));
    printf("%d", sum);
    return 0;
}
```
The output of the given C program is ________. (Answer in integer)
